#!/usr/bin/env python3
# flake8: noqa
# ruff: noqa
import re
import sys
import shutil
import os
import tempfile
import subprocess
import argparse
from os import path
from typing import List
import copy

COLOR_BOLD_RED = "\033[1;31m"
COLOR_BOLD_GREEN = "\033[1;32m"
COLOR_BOLD_CYAN = "\033[1;36m"
COLOR_RESET = "\033[0m"


class UE:
    def __init__(self):
        self.ue_id = 0
        self.imsi = ""
        self.imei = ""
        self.ip_ver = "0"
        self.pmi = ""
        self.ri = ""
        self.cqi = "6"
        self.ue_cat = "3"
        self.integrity = "NULL"
        self.crypt_alg = "NULL"
        self.auth = ""
        self.ck_ik = ""
        self.op_key = ""
        self.xres = ""
        self.old_guti = ""
        self.reattach_mode = ""
        self.ue_capabilities = ""
        self.ue_pool = ""

    def __str__(self):
        ret = "UE-{}\n".format(self.ue_id)
        ret += "\tIMSI   = {}\n".format(self.imsi)
        ret += "\tINT    = {}\n".format(self.integrity)
        ret += "\tCRYPT  = {}\n".format(self.crypt_alg)
        ret += "\tAUTH   = {}\n".format(self.auth)
        ret += "\tOP_KEY = {}\n".format(self.op_key)
        return ret


def get_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('-i', '--input', type=str, required=False, help="Input file")
    parser.add_argument('-o', '--output', type=str, required=False, help="Output file")

    arguments = parser.parse_args()

    if arguments.input is not None and not path.exists(arguments.input):
        exception("File '{}' doesn't exist".format(arguments.input))

    return arguments


def exception(message):
    raise Exception("{}{}{}".format(COLOR_BOLD_RED, message, COLOR_RESET))
    # exit(1)


def check_system():
    if sys.version_info.major != 3 and sys.version_info.minor >= 6:
        exception("Only python3 supported!")

    if shutil.which("lua") is None:
        message = "{}lua is not installed{}{}".format(COLOR_BOLD_RED, COLOR_RESET, "\n")
        message += "{}Run {}sudo apt-get install lua5.1{}".format(COLOR_BOLD_RED, COLOR_BOLD_CYAN, COLOR_RESET)
        raise LuaLibExeption


def get_exec_function():
    ret = "function exec(str) \n"
    ret += "    print(str) \n"
    ret += "end \n"

    return ret


def read_epc_config_content(epc_config_filename):
    lines = ""
    try:
        f = open(epc_config_filename)
        for line in f.readlines():
            if re.search(r"sleep\s*\(", line):
                line = "--" + line
            elif re.search(r"table.getn\s*\(", line):
                line = line.replace("table.getn(", "#(")
            elif re.search(r"print\s*\(", line):
                continue
            elif re.search("eth4", line):
                line = re.sub("eth4", "eth3", line)
            lines += line
        # print(lines)
    except IOError:
        exception("File {} doesn't exist".format(epc_config_filename))

    return lines


def parse_epc_lua_config(epc_content):
    tmp_file = tempfile.NamedTemporaryFile(mode="w", delete=False)
    tmp_file.write(epc_content)
    tmp_file.close()

    output = subprocess.getoutput("lua {}".format(tmp_file.name))
    os.unlink(tmp_file.name)

    if output == "" or output.find("syntax error") != -1:
        exception("{}{}Cannot parse epc config".format(output, "\n"))

    return output


class Line:
    def __init__(self):
        self.operation = ""
        self.paramList = dict()
        self.flags = list()

    def __lt__(self, other):

        operation = self.operation < other.operation

        if self.operation == other.operation:

            # sort bearers by ue, then id
            if "ue" in self.paramList and "ue" in other.paramList:
                ue_cmp = self.paramList["ue"] < other.paramList["ue"]

                if self.paramList["ue"] == other.paramList["ue"]:
                    if "id" in self.paramList and "id" in other.paramList:
                        id_cmp = self.paramList["id"] < other.paramList["id"]
                        return id_cmp

                return ue_cmp

            # sort other params by id
            if "id" in self.paramList and "id" in other.paramList:
                id_cmp = self.paramList["id"] < other.paramList["id"]
                return id_cmp

        return operation

    def __str__(self):
        ret = "{}  ".format(self.operation)

        for flag in self.flags:
            ret += "{} ".format(flag)

        for key in self.paramList:
            ret += "{}={} ".format(key, self.paramList[key])

        return ret

    def str_multiline(self):
        ret = "operation = {}\n".format(self.operation)
        for p in self.paramList:
            ret += "{}\n".format(p)

        return ret


def split_lines_to_variables(epc_config_output):
    lines_list: List[Line] = list()
    for line_str in epc_config_output.split("\n"):
        if line_str.strip() == "":
            continue

        line = Line()
        lines = line_str.split(" ")
        line.operation = lines[0]
        if len(lines) > 1:
            for p in lines[1:]:
                if p.find("=") != -1:
                    assignment = p.split("=")
                    key = assignment[0].lower()
                    value = assignment[1].lower()

                    if key in ("id", "ue"):
                        if "-" in value or ".." in value:
                            value = value
                        else:
                            value = int(value)
                    line.paramList[key] = value
                else:
                    line.flags.append(p)

        lines_list.append(line)

    return lines_list


def sort_lines(epc_lines):
    epc_lines.sort()
    return epc_lines


def get_ue_data(epc_lines):
    ue_list: List[UE] = list()
    sec_op_key = None
    imei_start = 4901309095204600

    for line in epc_lines:

        if line.operation == "set_param":
            for key, value in line.paramList.items():
                if key == "sec_op_key":
                    sec_op_key = value
                pass

        if line.operation == "set_ue":
            ue = UE()

            for key, value in line.paramList.items():

                if key == "id":
                    ue.ue_id = value
                elif key == "imsi":
                    ue.imsi = value.replace(":", "")
                elif key == "eea":
                    ue.crypt_alg = value.upper()
                elif key == "eia":
                    ue.integrity = value.upper()
                elif key == "sec_key":
                    ue.auth = value.upper()

            if sec_op_key is not None:
                ue.op_key = sec_op_key

            ue.imei = imei_start + int(ue.ue_id)

            ue_list.append(ue)

    return ue_list


def get_ue_db(ues: List[UE]):
    if len(ues) == 0:
        return "UE list is empty"

    first_ue = ues[0]
    last_ue = ues[len(ues) - 1]
    same_ues = True

    for ue in ues[1:]:
        tmp_ue = copy.deepcopy(ue)
        tmp_ue.ue_id = first_ue.ue_id
        tmp_ue.imsi = first_ue.imsi
        tmp_ue.imei = first_ue.imei
        tmp_ue.auth = first_ue.auth
        diff = tmp_ue.__dict__.items() ^ first_ue.__dict__.items()
        if len(diff) != 0:
            same_ues = False

    if same_ues:
        ues.clear()
        first_ue.ue_id = "{}-{}".format(first_ue.ue_id, last_ue.ue_id)
        ues.append(first_ue)

    ret = "#UEID; IMSI; IMEISV; IPVER; PMI; RI; CQI; UECAT; INTEGRTALG; CRYPTALG; AUTH; CK-IK; OP_KEY; XRES; "
    ret += "OLD_GUTI; REATTACH_MODE; UE_CAPABILITIES; UE_POOL\n"
    ret = ""

    for ue in ues:
        items = ue.__dict__.items()
        for item in items:
            ret += "{};".format(item[1])

        ret = ret[:-1]
        ret += "\n"

    return ret


def replace_variables_with_string(config):
    pattern = "set\\s+(.+)=(.+)"

    for line in config.split("\n"):
        match = re.search(pattern, line)
        if match:
            var = "$" + match.group(1)
            val = match.group(2).replace("\"", "")
            config = config.replace(var, val)
            config = config.replace(line + "\n", "")

    return config


def run(debug_args=None):
    check_system()

    if debug_args is not None:
        args_input = debug_args.get("input")
        args_coco = debug_args.get("coco")
        # args_output = debug_args.get("output")
    else:
        args = get_arguments()
        args_input = args.input
        args_coco = None
        # args_output = args.output

    if args_input is not None:
        epc_file_name = args_input
    else:
        epc_file_name = "configs/epc.lua"

    epc_config = read_epc_config_content(epc_file_name)
    if epc_file_name.find(".cfg") != -1:
        epc_output = epc_config
    else:
        epc_config = get_exec_function() + epc_config
        epc_output = parse_epc_lua_config(epc_config)

    # print("{} - OK".format(epc_file_name))
    if epc_output.find("stack traceback") != -1:
        message = "{}\n{}Cannot execute {}".format(epc_output, COLOR_BOLD_RED, epc_file_name)
        message += "\nCheck if lua file contains proper config{}".format(COLOR_RESET)
        raise LuaExeption

    epc_output = replace_variables_with_string(epc_output)

    epc_lines = split_lines_to_variables(epc_output)

    if args_coco is not None:
        epc_lines = sort_lines(epc_lines)
        return epc_lines

    # print(epc_output)
    print("-------------------------------------")

    with open("EPC_config.cfg", "w") as epc_cfg_file:
        epc_cfg_file.write(epc_output)
    epc_cfg_file.close()

    ues = get_ue_data(epc_lines)

    ue_db = get_ue_db(ues)

    with open("ue._db", "w") as ue_db_file:
        ue_db_file.write(ue_db)
    ue_db_file.close()
    # print(ue_db)

    print("-------------------------------------")


class LuaExeption(BaseException):
    def __init__(self, message="Check if lua file contains proper config"):
        self.message = message
        super().__init__(self.message)


class LuaLibExeption(BaseException):
    def __init__(self, message="Lua lib is not installed. Run sudo apt-get install lua5.1"):
        self.message = message
        super().__init__(self.message)


if __name__ == '__main__':
    run()
